-- Hand-written ev lessons, days 6-30 (100 stacks: one per day and learner goal).
-- Tagged handwritten-v1, so Days 1-30 pick them over older generated stacks (mobile/lib/handwritten.ts).
-- Safe to run more than once: stacks upsert on id, and each stack's slides are replaced.
-- Too large for Lovable to paste: the load-handwritten-lessons edge functions write these same rows
-- (scripts/lessons/export_loader.py).
BEGIN;
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tags = EXCLUDED.tags, stack_type = EXCLUDED.stack_type,
  authored_lesson = EXCLUDED.authored_lesson, duration_minutes = EXCLUDED.duration_minutes,
  published_at = COALESCE(stacks.published_at, EXCLUDED.published_at);

DELETE FROM slides WHERE stack_id IN ('6596755b-bc3c-5472-9ac1-15215c9d67c2'::uuid, 'c0b35afa-808d-519a-8e3f-20078ff2f7e5'::uuid, 'a1261cb9-2e26-5be2-a997-669fcaba7236'::uuid, 'c31e17c5-28d7-561a-8c97-f02819b23bfc'::uuid, '012d93ca-6514-53f4-9c36-9bc577ce3558'::uuid, '1d264612-e1c7-5def-abc4-1d8a906e05de'::uuid, '954b9bfc-169d-53b3-ab77-a3123c1dac95'::uuid, 'ce4b8ce3-66aa-52fd-ace7-93155fea259a'::uuid, 'e933ea35-ea66-5bb9-a306-d1f1a13cda64'::uuid, 'c3d21d21-9dbd-593e-ab79-7960d237186b'::uuid, 'd29ea91d-e934-526e-821b-128543ed2715'::uuid, '29d89199-d7c0-51ee-8455-42b02926e43d'::uuid, '121926c3-2df7-5123-8fec-11776a0152a4'::uuid, '5ebe6a1d-8195-5434-a370-2b15d4c3506e'::uuid, 'dfbb96da-e552-58db-9e37-520c31e0cb1b'::uuid, '83c6b71a-5523-5324-96de-4d6cc6fac716'::uuid, 'e015fc17-41a0-5fea-bcd6-78bcb01fa58b'::uuid, '724d92f4-3b18-51b8-94d0-3a460268e5c7'::uuid, '9ad6d9c6-ab5e-564f-a5da-4e63fbd56481'::uuid, '4be50b9a-77ba-56e5-800b-b047c0ad3516'::uuid, '3d70f4bc-1489-5034-91c2-7aa0ed56dbf8'::uuid, '6b196ece-2699-5c6b-aa3c-fb8eab437163'::uuid, 'ce15b37f-0755-582f-8fd2-7598b6e11aeb'::uuid, '8d31ccd2-bf8f-5013-8acc-5f69e93f7c9d'::uuid, 'b4ddad0a-e2ab-50da-af31-91464f4921dd'::uuid, '951f8ea1-38e0-5dd0-ad8a-8c5f2e4b7c99'::uuid, '77d4ef8b-ab3c-5f6a-b7da-3ccae5c8afe0'::uuid, '14d857d6-b53a-5eae-ae2a-dab848a7f5e2'::uuid, '2e3d7e13-aae5-5195-b29e-203c56a7e3f7'::uuid, 'aabc5e65-c3c3-5934-b027-8e1418bc112b'::uuid, 'cbdbf1a7-122f-5356-a3bd-4a4e827c4082'::uuid, 'faffd0b1-cb16-5367-bf89-732a2b9f66d9'::uuid, 'fe2c3f45-2ecf-50bb-a239-6251fd74a84c'::uuid, '9ccf99de-6fe5-5011-839a-55fd660c02c2'::uuid, '6c714d4f-985a-5655-8f0b-3094a3e4d916'::uuid, '79649d0f-5add-5937-a1b5-e1d25138f647'::uuid, '6787a4a3-f46b-5871-ad5b-dba94bb7f206'::uuid, 'fad6fbec-f40e-5568-bc88-426fb7476794'::uuid, '45133ecc-0e7d-5bf7-bd2c-967170954e2b'::uuid, '3974a777-4320-5959-a4a1-d5313ddd7735'::uuid, '4280c09c-9852-549e-b8ba-b97ef9a75474'::uuid, '325b3756-16cd-5cdd-aad5-71bf54d22b93'::uuid, '7b3e12e0-c3fb-56c4-9525-ebee9